def _skip_ratio_threshold() -> float:
    raw = os.environ.get("LARCH_SKIP_RATIO_THRESHOLD", "")
    if not raw:
        return 0.5
    try:
        value = float(raw)
    except ValueError:
        _err(f"⚠ review-and-fix: invalid LARCH_SKIP_RATIO_THRESHOLD={raw}; using 0.5")
